<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useWorkbench} from './stores/workbench'
import Icon from './components/Icon.vue'
import Dialog from './components/Dialog.vue'
import NewProject from './components/NewProject.vue'
import ModelDefaultSelect from './components/ModelDefaultSelect.vue'
const store=useWorkbench(),route=useRoute(),router=useRouter(),createOpen=ref(false),searchOpen=ref(false),query=ref(''),sidebarOpen=ref(false)
const modelMenu=ref<HTMLDetailsElement>()
watch(()=>route.fullPath,()=>{if(modelMenu.value)modelMenu.value.open=false})
const navigation=[{label:'创作工作台',path:'/',icon:'LayoutDashboard'},{label:'我的作品',path:'/projects',icon:'FolderOpen'},{label:'灵感收件箱',path:'/ideas',icon:'Lightbulb'},{label:'制作流程',path:'/workflow',icon:'Workflow'},{label:'素材与资产',path:'/library',icon:'Images'}]
const tools=[{label:'模型中心',path:'/models',icon:'Boxes'},{label:'Agent 团队',path:'/agents',icon:'Bot'},{label:'协作运行',path:'/runs',icon:'GitBranch'},{label:'工具与环境',path:'/tools',icon:'Plug'},{label:'任务中心',path:'/tasks',icon:'ListTodo'},{label:'待我确认',path:'/approvals',icon:'CheckCheck'},{label:'经营与复盘',path:'/business',icon:'ChartNoAxesCombined'}]
const title=computed(()=>[...navigation,...tools,{path:'/settings',label:'工作区设置'},{path:'/creator-profile',label:'创作档案'}].find(n=>n.path===route.path)?.label??'作品工作区')
const results=computed(()=>{const q=query.value.trim().toLowerCase();if(!q)return [];return [...store.state.projects.filter(p=>p.title.toLowerCase().includes(q)).map(p=>({title:p.title,note:'作品',path:'/projects/'+p.id})),...store.catalog.nodes.filter(n=>(n.id+n.name).toLowerCase().includes(q)).slice(0,8).map(n=>({title:n.id+' '+n.name,note:'制作节点',path:'/workflow?node='+n.id}))]})
function keyboard(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchOpen.value=!searchOpen.value}}
onMounted(()=>{store.init();window.addEventListener('keydown',keyboard)});onUnmounted(()=>window.removeEventListener('keydown',keyboard))
</script>
<template><div class="app-shell"><aside :class="['sidebar',{expanded:sidebarOpen}]"><RouterLink to="/" class="brand"><span class="brand-symbol"><i/><i/><i/></span><span>帧序<span class="brand-en">FRAME</span></span></RouterLink><button class="workspace-switch" @click="router.push('/creator-profile')"><span class="workspace-avatar">我</span><span><b>我的创作空间</b><small>独立创作者工作台</small></span><Icon name="ChevronsUpDown" :size="15"/></button><nav aria-label="主导航"><span class="nav-caption">创作空间</span><RouterLink v-for="n in navigation" :to="n.path" :key="n.path" :class="['nav-item',{active:n.path==='/'?route.path==='/':route.path.startsWith(n.path)}]" @click="sidebarOpen=false"><Icon :name="n.icon"/><span>{{n.label}}</span><span class="nav-count" v-if="n.path==='/projects'">{{store.state.projects.length}}</span><span class="new-dot" v-if="n.path==='/ideas'&&store.state.ideas.length"/></RouterLink><span class="nav-caption second">制作与协作</span><RouterLink v-for="n in tools" :key="n.path" :to="n.path" :class="['nav-item',{active:route.path===n.path}]" @click="sidebarOpen=false"><Icon :name="n.icon"/><span>{{n.label}}</span><span class="nav-count" v-if="n.path==='/tasks'&&store.state.tasks.some(t=>!t.deletedAt&&t.status==='BLOCKED')">{{store.state.tasks.filter(t=>!t.deletedAt&&t.status==='BLOCKED').length}}</span></RouterLink></nav><div class="sidebar-bottom"><div class="workspace-note"><span class="status-dot"/>{{store.connection==='server'?'本机服务已连接':'浏览器本地保存'}}<small>{{store.connection==='server'?'项目数据保存在数据库':'文件素材保存在 IndexedDB'}}</small></div><RouterLink to="/settings" class="nav-item"><Icon name="Settings2"/><span>工作区设置</span></RouterLink><div class="sidebar-signature">Made for your next idea.<span>帧序 · 0.2</span></div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" aria-label="打开菜单" @click="sidebarOpen=!sidebarOpen"><Icon name="Menu"/></button><span class="breadcrumb-home">工作空间</span><Icon name="ChevronRight" :size="13"/><b>{{title}}</b></div><div class="topbar-actions"><details ref="modelMenu" class="global-model-control"><summary aria-label="选择全局默认模型"><Icon name="Boxes" :size="16"/><span>全局模型</span><b>{{store.state.models.find(m=>m.id===store.state.globalBindings.$default)?.name??'未选择'}}</b><Icon name="ChevronsUpDown" :size="12"/></summary><div class="global-model-popover"><ModelDefaultSelect scope="GLOBAL" label="全局默认模型"/><p>未单独覆盖的角色、作品和节点自动继承。仅用于模型已声明支持的能力；TTS、图像等可另设能力默认。</p><RouterLink to="/models" class="text-link">管理模型与能力默认<Icon name="ArrowUpRight" :size="13"/></RouterLink></div></details><button class="global-search" @click="searchOpen=true"><Icon name="Search" :size="15"/><span>搜索作品、节点…</span><kbd>⌘ K</kbd></button><span class="topbar-divider"/><button class="icon-btn" aria-label="查看待确认事项" @click="router.push('/approvals')"><Icon name="Bell" :size="19"/></button><button class="user-avatar" aria-label="创作档案" @click="router.push('/creator-profile')">我</button></div></header><main><RouterView v-slot="{Component}"><Transition name="page" mode="out-in"><component :is="Component" :key="route.path" @create="createOpen=true"/></Transition></RouterView></main><footer class="main-footer"><span><i/>让创作顺畅一点，让表达自由一点。</span><span>{{store.catalog.nodes.length}} 个制作节点 · 人机协作</span></footer></div><NewProject :open="createOpen" @close="createOpen=false"/><Dialog :open="searchOpen" title="找到下一步" @close="searchOpen=false"><div class="search-input"><Icon name="Search"/><input v-model="query" placeholder="作品名称、N24、脚本、模型…" autofocus></div><div class="search-results"><button v-for="r in results" :key="r.path+r.title" @click="router.push(r.path);searchOpen=false"><Icon name="ArrowUpRight"/><span>{{r.title}}<small>{{r.note}}</small></span><Icon name="ChevronRight"/></button><p v-if="query&&!results.length" class="empty-copy">没有找到匹配内容，试试节点编号或关键词。</p><p v-if="!query" class="empty-copy">输入作品名称或节点关键词，快速返回创作现场。</p></div></Dialog><Transition name="toast"><div v-if="store.notice" role="status" :class="['toast',store.noticeKind]"><Icon :name="store.noticeKind==='error'?'AlertCircle':'CheckCircle2'"/>{{store.notice}}</div></Transition></div></template>
